/**
 * Bulk import/export helpers shared by the Products, Vendors and Customers
 * screens.
 *
 * Everything here is deliberately free of page/SQL concerns so the fiddly parts
 * (CSV parsing, loose header matching, Indonesian number parsing, collision
 * resolution, and the downloadable templates) live in one place and can be unit
 * tested without React or a database. The screens own only the column config and
 * the actual INSERTs.
 *
 * Import policy (agreed with the owner): the operation is *additive*. A row that
 * carries no human ID gets one auto-generated by the app; a row whose ID already
 * exists in the database, or repeats inside the same file, is reported as a
 * conflict and skipped — an import never overwrites records the owner already has.
 */

import * as XLSX from "xlsx";

/** A raw sheet row: header text -> cell text. */
export type BulkRow = Record<string, string>;

/** One importable/exportable column of an entity. */
export interface ColumnDef {
  /** Canonical key used by the screen code. */
  key: string;
  /** Human header label written to the file (Indonesian). */
  label: string;
  /** Extra header spellings accepted when reading a file. */
  aliases?: string[];
  /** Column width (chars) for the Excel template. */
  width?: number;
}

/** A row that was skipped because its identity already exists or repeats. */
export interface Conflict<T> {
  row: T;
  reason: "existing" | "duplicate_in_file";
}

/** Trim, lower-case and collapse inner spaces so header matching is forgiving. */
function normHeader(value: string): string {
  return String(value).trim().toLowerCase().replace(/\s+/g, " ");
}

/** Map every normalised header spelling (label + aliases) to its canonical key. */
function headerIndex(columns: ColumnDef[]): Record<string, string> {
  const index: Record<string, string> = {};
  for (const column of columns) {
    index[normHeader(column.label)] = column.key;
    for (const alias of column.aliases ?? []) index[normHeader(alias)] = column.key;
  }
  return index;
}

/**
 * Re-key raw sheet rows onto canonical keys, dropping unknown columns and
 * filling missing ones with an empty string.
 */
export function normalizeRows(raw: BulkRow[], columns: ColumnDef[]): BulkRow[] {
  const index = headerIndex(columns);
  return raw.map((row) => {
    const out: BulkRow = {};
    for (const column of columns) out[column.key] = "";
    for (const [header, value] of Object.entries(row)) {
      const key = index[normHeader(header)];
      if (key) out[key] = value;
    }
    return out;
  });
}

/**
 * Parse an Indonesian money/quantity cell. Tolerates `Rp`, thin spaces, a
 * `.` thousands separator and a `,` decimal separator (`1.000,5` -> 1000.5).
 */
export function parseIdNumber(value: string | number): number {
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  let raw = String(value).replace(/[^\d.,-]/g, "");
  if (!raw) return 0;
  const hasComma = raw.includes(",");
  const hasDot = raw.includes(".");
  if (hasComma) raw = raw.replace(/\./g, "").replace(",", ".");
  else if (hasDot && /^-?\d{1,3}(\.\d{3})+$/.test(raw)) raw = raw.replace(/\./g, "");
  const n = Number(raw);
  return Number.isFinite(n) ? n : 0;
}

/** Read the first sheet of an uploaded file (CSV or Excel) into raw rows. */
export async function readRows(file: File): Promise<BulkRow[]> {
  const buffer = await file.arrayBuffer();
  const workbook = XLSX.read(buffer, { type: "array" });
  const first = workbook.SheetNames[0];
  if (!first) return [];
  const sheet = workbook.Sheets[first];
  const json = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet, {
    defval: "",
    raw: false,
  });
  return json.map((row) => {
    const out: BulkRow = {};
    for (const [key, value] of Object.entries(row)) {
      out[String(key)] = value == null ? "" : String(value).trim();
    }
    return out;
  });
}

/** RFC-4180 quoting: wrap when the cell holds a comma, quote, or newline. */
function escapeCsv(value: string | number): string {
  const text = value == null ? "" : String(value);
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

/** Serialise rows to a CSV string with a UTF-8 BOM so Excel opens it cleanly. */
export function toCsv(rows: BulkRow[], columns: ColumnDef[]): string {
  const header = columns.map((column) => escapeCsv(column.label)).join(",");
  const body = rows.map((row) =>
    columns.map((column) => escapeCsv(row[column.key] ?? "")).join(",")
  );
  return `\uFEFF${[header, ...body].join("\r\n")}\r\n`;
}

function saveBlob(filename: string, blob: Blob): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  URL.revokeObjectURL(url);
}

/** Download rows as an editable, Excel-friendly CSV. */
export function downloadCsv(filename: string, rows: BulkRow[], columns: ColumnDef[]): void {
  saveBlob(filename, new Blob([toCsv(rows, columns)], { type: "text/csv;charset=utf-8" }));
}

/** Download rows as an .xlsx workbook. */
export function downloadXlsx(
  filename: string,
  rows: BulkRow[],
  columns: ColumnDef[],
  sheetName = "Data"
): void {
  const aoa = [
    columns.map((column) => column.label),
    ...rows.map((row) => columns.map((column) => row[column.key] ?? "")),
  ];
  const sheet = XLSX.utils.aoa_to_sheet(aoa);
  sheet["!cols"] = columns.map((column) => ({ wch: column.width ?? 18 }));
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, sheet, sheetName);
  XLSX.writeFile(workbook, filename);
}

/**
 * Split incoming rows into those safe to insert and those to skip.
 *
 * A row with an empty identity (e.g. no SKU) counts as `fresh` because the
 * screen will auto-generate one. Otherwise the row conflicts when any of its
 * keys already exists in the database (`existing`) or repeats earlier in the
 * same file (`duplicate_in_file`). Comparison is case-insensitive.
 */
export function resolveCollisions<T>(options: {
  incoming: T[];
  /** All identity keys of a row; empty entries are ignored. */
  keysOf: (row: T) => Array<string | null | undefined>;
  /** Lower-cased set of keys already present in the database. */
  existingKeys: Set<string>;
}): { fresh: T[]; conflicts: Conflict<T>[] } {
  const seen = new Set<string>();
  const fresh: T[] = [];
  const conflicts: Conflict<T>[] = [];

  for (const row of options.incoming) {
    const keys = options
      .keysOf(row)
      .map((key) => String(key ?? "").trim().toLowerCase())
      .filter(Boolean);

    // No usable identity -> let the screen auto-generate it.
    if (keys.length === 0) {
      fresh.push(row);
      continue;
    }

    if (keys.some((key) => options.existingKeys.has(key))) {
      conflicts.push({ row, reason: "existing" });
      continue;
    }
    if (keys.some((key) => seen.has(key))) {
      conflicts.push({ row, reason: "duplicate_in_file" });
      continue;
    }
    keys.forEach((key) => seen.add(key));
    fresh.push(row);
  }

  return { fresh, conflicts };
}

/** Drop rows whose required fields are missing, returning what is left. */
export function keepValid(
  rows: BulkRow[],
  requiredKeys: string[]
): { valid: BulkRow[]; invalid: BulkRow[] } {
  const valid: BulkRow[] = [];
  const invalid: BulkRow[] = [];
  for (const row of rows) {
    const ok = requiredKeys.every((key) => String(row[key] ?? "").trim() !== "");
    (ok ? valid : invalid).push(row);
  }
  return { valid, invalid };
}

